typedef unsigned int size_t;
extern "C" size_t strlen(const char *);

class string_buf
{
public:
    void *data;
    int ref_count;
    int char_length;
};

class stringx
{
public:
    char *chars;
    string_buf *my_buf;

    stringx();
    stringx(const stringx &);
    ~stringx();
    void make_room(int);
    void append(const char *, int = -1);
    void append(const stringx &);
    stringx &operator=(const stringx &);
    stringx &operator+=(const char *);
    char *data() const { return chars; }
};

inline stringx operator+(const stringx &lhs, const char *rhs)
{
    stringx foo;
    int len = strlen(rhs);
    foo.make_room(len + lhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs, len);
    return foo;
}

class BoxText
{
public:
    void ReadFromFile(char *, bool);
    int makeBox(int, int, bool = false, float = -1, int = -1);
};

extern int ksGlobalTextLanguage;
enum { LANGUAGE_FRENCH = 2, LANGUAGE_GERMAN = 3 };

class LegalFrontEnd
{
    char padding0[0x134];
    stringx path;
    char padding1[0x14];
    BoxText *legal_babble;

public:
    void Load();
};

void LegalFrontEnd::Load()
{
    stringx tmp = path+"legal_text_";
#ifdef TARGET_PS2
    tmp = tmp + "ps2";
#elif defined(TARGET_XBOX)
    tmp = tmp + "xbox";
#elif defined(TARGET_GC)
    tmp = tmp + "gc";
#else
#error Platform not declared!
#endif

    if(ksGlobalTextLanguage == LANGUAGE_FRENCH)
        tmp += "_fr";
    else if(ksGlobalTextLanguage == LANGUAGE_GERMAN)
        tmp += "_ge";
    tmp += ".txt";

    legal_babble->ReadFromFile((char*) (tmp.data()), false);
    legal_babble->makeBox(550, 300);
}
